custom_css:
/* Eat&Go Background & Aesthetic Fix - Unquoted & Clean */
html body .elementor-190 div.elementor-element.elementor-element-1e4962ce,
html body div.elementor-element.elementor-element-1e4962ce {
  background-size: cover !important;
  background-position: center center !important;
  background-repeat: no-repeat !important;
  position: relative !important;
  overflow: hidden !important;
}

html body .elementor-190 div.elementor-element.elementor-element-1e4962ce::before,
html body div.elementor-element.elementor-element-1e4962ce::before {
  content: '' !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  opacity: 1 !important;
  background: linear-gradient(180deg, rgba(0,0,0,0.15) 0%, rgba(0,0,0,0.95) 75%) !important;
  z-index: 1 !important;
  pointer-events: none !important;
}

html body .elementor-190 div.elementor-element.elementor-element-1e4962ce * {
  position: relative;
  z-index: 2;
}

/* Product Specific Backgrounds - Unquoted URLs */
html body .e-loop-item-446 div.elementor-element.elementor-element-1e4962ce {
